    {
      "clause_id": "SYN-0001 §1",
      "text": "Requires individuals keeping a firearm in a residence to store it in a locked container when not carried or used."
    },
    {
      "clause_id": "SYN-0001 §2",
      "text": "Directs the Department to issue a storage certificate to applicants for a $25 fee."
